WITH cust_monthly AS (SELECT cr.cr_returning_customer_sk, i.i_category, d.d_year AS year, d.d_month_seq AS month_seq, SUM(cr.cr_net_loss) AS month_net_loss, SUM(cr.cr_return_quantity) AS month_quantity, SUM(cr.cr_return_amount) AS month_return_amount, sm.sm_type AS ship_mode_type FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cr.cr_returning_customer_sk, i.i_category, d.d_year, d.d_month_seq, sm.sm_type) SELECT cr_returning_customer_sk, i_category, year, month_seq, month_net_loss, month_quantity, month_return_amount, ship_mode_type, SUM(month_net_loss) OVER (PARTITION BY cr_returning_customer_sk ORDER BY year, month_seq ROWS UNBOUNDED PRECEDING) AS cumulative_net_loss, CASE WHEN month_net_loss > 1000 THEN 'High' WHEN month_net_loss BETWEEN 500 AND 1000 THEN 'Medium' ELSE 'Low' END AS loss_level, RANK() OVER (PARTITION BY year, month_seq ORDER BY month_net_loss DESC) AS month_loss_rank FROM cust_monthly WHERE year BETWEEN 2020 AND 2022 ORDER BY cr_returning_customer_sk, year, month_seq
